"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps, ReactNode } from "react";

export type SkeletonShimmerPrimitiveProps = Omit<ComponentProps<typeof motion.div>, "children"> & { children: ReactNode };

export function SkeletonShimmerPrimitive({ children, ...props }: SkeletonShimmerPrimitiveProps) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.div {...props} aria-busy="true" style={{ ...props.style, position: "relative", overflow: "hidden" }}>
      {children}
      <motion.span
        aria-hidden="true"
        initial={{ x: "-140%" }}
        animate={{ x: reduceMotion ? "0%" : "180%" }}
        transition={{ duration: reduceMotion ? 0.12 : 1.4, ease: "linear", repeat: reduceMotion ? 0 : Infinity }}
        style={{ position: "absolute", inset: 0, background: "linear-gradient(90deg, transparent, rgb(255 255 255 / 0.14), transparent)", pointerEvents: "none" }}
      />
    </motion.div>
  );
}
